/* smart_region.js */
try {
// Smart refresh for sorted and filtered lists: a click on a `[data-smart-link]` or the submit of a
// `[data-smart-form]` (GET) fetches the same URL and swaps only the `[data-smart-region]` elements (matched by id),
// so scroll, open menus and the rest of the page stay put. `[data-smart-attrs="href"]` elements get just those
// attributes copied. Any failure falls back to a normal navigation.
(function () {
  let controller = null;

  async function refresh(url, fallback) {
    if (controller) controller.abort();
    controller = new AbortController();
    const endBusy = window.ccBusy ? window.ccBusy.begin() : null;
    try {
      const resp = await fetch(url, { headers: { "X-Requested-With": "fetch" }, signal: controller.signal });
      if (!resp.ok) throw new Error("refresh failed");
      const next = new DOMParser().parseFromString(await resp.text(), "text/html");
      const regions = document.querySelectorAll("[data-smart-region]");
      let swapped = 0;
      regions.forEach((region) => {
        const fresh = region.id && next.getElementById(region.id);
        if (fresh) {
          region.innerHTML = fresh.innerHTML;
          swapped += 1;
        }
      });
      if (!swapped) throw new Error("no region");
      document.querySelectorAll("[data-smart-attrs]").forEach((el) => {
        const fresh = el.id && next.getElementById(el.id);
        if (!fresh) return;
        el.dataset.smartAttrs.split(",").forEach((attr) => el.setAttribute(attr, fresh.getAttribute(attr) || ""));
      });
      history.replaceState(null, "", url);
      document.dispatchEvent(new CustomEvent("cc-region-refreshed"));
    } catch (err) {
      if (err.name === "AbortError") return;
      fallback();
    } finally {
      if (endBusy) endBusy();
    }
  }

  // Refreshes the regions of the current page after a change; resolves false when the page has none.
  window.ccSmartRefresh = function () {
    if (!document.querySelector("[data-smart-region]")) return Promise.resolve(false);
    return new Promise((resolve) => {
      refresh(window.location.href, () => resolve(false)).then(() => resolve(true));
    });
  };

  // A change to a note (pin, delete, bulk edit) refreshes the regions of a page that has them.
  document.addEventListener("cc-entity-changed", function (e) {
    if (!e.detail || e.detail.type !== "notebook" || !document.querySelector("[data-smart-region]")) return;
    e.detail.claimed = true;
    window.ccSmartRefresh();
  });

  document.addEventListener("click", function (e) {
    const link = e.target.closest("a[data-smart-link]");
    if (!link || e.defaultPrevented || e.metaKey || e.ctrlKey || e.shiftKey || e.button) return;
    e.preventDefault();
    refresh(link.href, () => { window.location.href = link.href; });
  });

  document.addEventListener("submit", function (e) {
    const form = e.target;
    if (!form.matches || !form.matches("form[data-smart-form]")) return;
    e.preventDefault();
    const params = new URLSearchParams(new FormData(form));
    const url = new URL(form.getAttribute("action") || window.location.pathname, window.location.href);
    url.search = params.toString();
    refresh(url.toString(), () => { window.location.href = url.toString(); });
  });
})();

} catch (err) { console.error('smart_region.js', err); }
/* finance_task_rows.js */
try {
// Pending transactions rows in the task edit form (templates/_task_transactions.html): a row added from the template
// gets its own key so each Tags dropdown posts under its own name, and the Type choice decides which accounts the
// row asks for.
(function () {
  let counter = 0;

  function rekey(row) {
    counter += 1;
    const token = "n" + counter;
    row.querySelectorAll("*").forEach(function (el) {
      ["name", "id", "for", "data-ms-name"].forEach(function (attr) {
        const value = el.getAttribute(attr);
        if (value && value.indexOf("tmpl") !== -1) el.setAttribute(attr, value.replace(/tmpl/g, token));
      });
    });
    const key = row.querySelector('input[name="pt_key"]');
    if (key) key.value = token;
  }

  document.addEventListener("DOMContentLoaded", function () {
    const rows = document.getElementById("pending-tx-rows");
    if (!rows) return;
    new MutationObserver(function (changes) {
      changes.forEach(function (change) {
        change.addedNodes.forEach(function (node) {
          if (node.nodeType === 1 && node.matches(".pending-tx-edit")) rekey(node);
        });
      });
    }).observe(rows, { childList: true });
  });

  document.addEventListener("change", function (e) {
    const radio = e.target;
    if (!radio.matches || !radio.matches(".contact-type-radio") || radio.dataset.proxyName !== "pt_type") return;
    const proxy = document.getElementById(radio.dataset.proxyTarget);
    const row = proxy && proxy.closest(".pending-tx-edit");
    if (row) row.dataset.type = radio.value.toLowerCase();
  });
})();

} catch (err) { console.error('finance_task_rows.js', err); }
